from pathlib import Path
import json,base64
p=Path('character/james-west-carry-walk-keys-v1');o=p/'full-gait-review-v233';r=p.parents[1];j=json.loads((p/'material-repair-progress.json').read_bytes());dur=json.loads((o/'bare-manifest.json').read_bytes())['states'][0]['frameDurationsMs'];data={mode:['data:image/png;base64,'+base64.b64encode((r/row['candidateSources'][mode]['file']).read_bytes()).decode() for row in j['states']] for mode in ['bare','helmet']};data['master']='data:image/png;base64,'+base64.b64encode((p/'../james-west-master-carry-v1/registered-original-master.png').read_bytes()).decode()
html='''<!doctype html><meta charset="utf-8"><title>James carrying - full cycle review</title><style>body{background:#2f3a3f;color:#eee;font:16px Arial;margin:20px}button,select,input{margin:8px;padding:8px}canvas{max-width:100%;border:1px solid #526169}small{display:block;margin-top:12px;color:#cbd1d3}</style><h2>James carrying - full cycle and master comparison</h2><button id="toggle">Pause</button><button id="step">Next frame</button><select id="speed"><option value="1">Original timing</option><option value=".25">Quarter speed</option></select><input id="seek" type="range" min="0" max="48" value="0"><span id="status">Loading</span><br><canvas id="stage" width="1100" height="380"></canvas><small>Original standing master at left. Bare and helmet carrying use the same pivot and source timing. Provisional art review; normal game selection unchanged.</small><script>
const sources=DATA,durations=DUR;const total=durations.reduce((a,b)=>a+b,0),ctx=stage.getContext('2d');let elapsed=0,last=0,playing=true,rate=1,images={},seen=new Set();
async function load(url){let im=new Image();im.src=url;await im.decode();return im;}
function indexAt(ms){let x=ms%total;for(let i=0;i<49;i++){if(x<durations[i])return i;x-=durations[i];}return 48;}
function draw(i){ctx.fillStyle='#2f3a3f';ctx.fillRect(0,0,1100,380);ctx.font='16px Arial';ctx.fillStyle='#eee';const labels=['Original master','Bare carrying','Helmet carrying'];for(let n=0;n<3;n++){const im=n===0?images.master:images[n===1?'bare':'helmet'][i];ctx.fillText(labels[n],45+350*n,28);ctx.drawImage(im,45+350*n,52,256,256);ctx.strokeStyle='#697b83';ctx.beginPath();ctx.moveTo(45+350*n,276);ctx.lineTo(301+350*n,276);ctx.stroke();}document.getElementById('status').textContent=`Frame ${i}/48 | ${total} ms cycle | ${playing?'Playing':'Paused'}`;seek.value=i;seen.add(i);}
function tick(t){if(last&&playing)elapsed+=(t-last)*rate;last=t;draw(indexAt(elapsed));requestAnimationFrame(tick);}
toggle.onclick=()=>{playing=!playing;toggle.textContent=playing?'Pause':'Play';};step.onclick=()=>{playing=false;toggle.textContent='Play';let i=(indexAt(elapsed)+1)%49;elapsed=durations.slice(0,i).reduce((a,b)=>a+b,0)+durations[i]/2;};seek.oninput=()=>{playing=false;toggle.textContent='Play';let i=+seek.value;elapsed=durations.slice(0,i).reduce((a,b)=>a+b,0)+durations[i]/2;};speed.onchange=()=>rate=+speed.value;
(async()=>{images.master=await load(sources.master);for(let mode of ['bare','helmet'])images[mode]=await Promise.all(sources[mode].map(load));requestAnimationFrame(tick);})();
</script>'''.replace('DUR',json.dumps(dur)).replace('DATA',json.dumps(data));(o/'playback-review.html').write_text(html,encoding='utf-8');print(json.dumps(dict(cycleMs=sum(dur),htmlBytes=(o/'playback-review.html').stat().st_size)))

